package dev.scanplus.security;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
import java.io.*;
import java.nio.file.*;
import java.nio.file.attribute.PosixFilePermissions;
import java.security.MessageDigest;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import java.util.zip.ZipFile;
import static dev.scanplus.security.AppModels.*;

@Service
public class AppControlStore {
    static final long MAX_APK=64L*1024*1024;
    private final JdbcTemplate db; private final Clock clock; private final ObjectMapper json; private final Path directory;
    public AppControlStore(JdbcTemplate db,Clock clock,ObjectMapper json,@Value("${scanplus.apks-directory:./var/apks}") String directory){this.db=db;this.clock=clock;this.json=json;this.directory=Path.of(directory).toAbsolutePath().normalize();}
    private Timestamp now(){return Timestamp.from(clock.instant());}
    private void device(UUID id){if(db.queryForObject("SELECT COUNT(*) FROM devices WHERE id=? AND revoked=FALSE",Integer.class,id.toString())!=1)throw new ResponseStatusException(HttpStatus.NOT_FOUND);}
    private void lock(UUID id){device(id);db.queryForMap("SELECT id FROM devices WHERE id=? FOR UPDATE",id.toString());}
    private void audit(String actor,String action,UUID device,UUID command,String detail){db.update("INSERT INTO audit(event_time,actor,action,device_id,command_id,detail) VALUES(?,?,?,?,?,?)",now(),actor,action,device==null?null:device.toString(),command==null?null:command.toString(),detail);}
    private String encode(Object value){try{return json.writeValueAsString(value);}catch(Exception e){throw new IllegalStateException(e);}}
    private Map<String,Object> view(UUID id){return db.queryForMap("SELECT id,device_id,request_id,action,package_name,permission_name,artifact_id,created_at,expires_at,started_at,completed_at,state,detail,CAST(result_json AS VARCHAR) AS result_json FROM app_commands WHERE id=?",id.toString());}
    @Transactional public Map<String,Object> inventory(UUID id){device(id);var rows=db.queryForList("SELECT reported_at,CAST(inventory_json AS VARCHAR) AS inventory_json FROM app_inventories WHERE device_id=?",id.toString());if(rows.isEmpty())return Map.of("deviceId",id,"apps",List.of(),"canForceStop",false);try{var result=json.readValue((String)rows.get(0).get("INVENTORY_JSON"),Inventory.class);return Map.of("deviceId",id,"reportedAt",((Timestamp)rows.get(0).get("REPORTED_AT")).toInstant(),"apps",result.apps(),"canForceStop",result.canForceStop());}catch(Exception e){throw new IllegalStateException(e);}}
    @Transactional public void report(UUID id,Inventory input){lock(id);if(input.apps().stream().map(AppInfo::packageName).distinct().count()!=input.apps().size())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Duplicate app");db.update("MERGE INTO app_inventories(device_id,reported_at,inventory_json) KEY(device_id) VALUES(?,?,?)",id.toString(),now(),encode(input));}
    private void expire(UUID device){db.update("UPDATE app_commands SET state='EXPIRED',detail='Request expired before execution' WHERE device_id=? AND state='PENDING' AND expires_at<=?",device.toString(),now());db.update("UPDATE app_commands SET state='FAILED',detail='Execution lease expired; refresh inventory before retrying' WHERE device_id=? AND state='RUNNING' AND started_at<=?",device.toString(),Timestamp.from(clock.instant().minusSeconds(600)));}
    @Transactional public List<Map<String,Object>> commands(UUID device){device(device);expire(device);return db.queryForList("SELECT id,device_id,request_id,action,package_name,permission_name,artifact_id,created_at,expires_at,started_at,completed_at,state,detail,CAST(result_json AS VARCHAR) AS result_json FROM app_commands WHERE device_id=? ORDER BY created_at DESC LIMIT 100",device.toString());}
    private boolean critical(String pkg){return Set.of("dev.velox.hardwaresecurity","android","com.android.systemui","com.android.settings","com.android.packageinstaller","com.google.android.packageinstaller").contains(pkg);}
    private AppInfo known(UUID device,String pkg){var rows=db.queryForList("SELECT CAST(inventory_json AS VARCHAR) AS inventory_json FROM app_inventories WHERE device_id=?",device.toString());if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.CONFLICT,"Refresh the app inventory first");try{return json.readValue((String)rows.get(0).get("INVENTORY_JSON"),Inventory.class).apps().stream().filter(a->a.packageName().equals(pkg)).findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.CONFLICT,"App is absent from the latest inventory"));}catch(ResponseStatusException e){throw e;}catch(Exception e){throw new IllegalStateException(e);}}
    @Transactional public Map<String,Object> queue(UUID device,Request input){
        lock(device);expire(device);
        boolean install=input.action()==Action.INSTALL, refresh=input.action()==Action.REFRESH, permission=input.action().name().endsWith("_PERMISSION");
        if((refresh||install)!=(input.packageName()==null)||install!=(input.artifactId()!=null)||permission!=(input.permission()!=null))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid app action parameters");
        String payload=encode(input);
        var prior=db.queryForList("SELECT id,payload FROM app_commands WHERE device_id=? AND request_id=?",device.toString(),input.requestId().toString());
        if(!prior.isEmpty()){if(!payload.equals(prior.get(0).get("PAYLOAD")))throw new ResponseStatusException(HttpStatus.CONFLICT);return view(UUID.fromString((String)prior.get(0).get("ID")));}
        if(!refresh&&!install){AppInfo app=known(device,input.packageName());if(critical(app.packageName())||app.critical()||(app.systemApp()&&input.action()!=Action.LAUNCH))throw new ResponseStatusException(HttpStatus.CONFLICT,"Core and management apps are protected");if(permission&&app.permissions().stream().noneMatch(p->p.name().equals(input.permission())))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Permission is not a requested runtime permission");}
        if(install&&db.queryForObject("SELECT COUNT(*) FROM app_apks WHERE id=?",Integer.class,input.artifactId().toString())!=1)throw new ResponseStatusException(HttpStatus.NOT_FOUND);
        if((install||input.action()==Action.UNINSTALL)&&Boolean.TRUE.equals(db.queryForMap("SELECT enabled FROM devices WHERE id=?",device.toString()).get("ENABLED")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Enter maintenance before installation or removal");
        if(db.queryForObject("SELECT COUNT(*) FROM app_commands WHERE device_id=? AND state IN ('PENDING','RUNNING')",Integer.class,device.toString())>=10)throw new ResponseStatusException(HttpStatus.CONFLICT,"Wait for the app queue to finish");
        UUID id=UUID.randomUUID();int ttl=input.ttlSeconds()==null?(install?600:180):input.ttlSeconds();
        db.update("INSERT INTO app_commands(id,device_id,request_id,action,package_name,permission_name,artifact_id,payload,created_at,expires_at,state,detail) VALUES(?,?,?,?,?,?,?,?,?,?,'PENDING','Waiting for terminal')",id.toString(),device.toString(),input.requestId().toString(),input.action().name(),input.packageName(),input.permission(),install?input.artifactId().toString():null,payload,now(),Timestamp.from(clock.instant().plusSeconds(ttl)));
        audit("administrator","APP_"+input.action()+"_REQUESTED",device,id,input.packageName()==null?input.action().name():input.packageName());return view(id);
    }
    @Transactional public Command next(UUID device){expire(device);var rows=db.queryForList("SELECT * FROM app_commands WHERE device_id=? AND state IN ('PENDING','RUNNING') ORDER BY created_at LIMIT 1",device.toString());return rows.isEmpty()?null:command(rows.get(0));}
    private Command command(Map<String,Object> row){UUID artifact=row.get("ARTIFACT_ID")==null?null:UUID.fromString((String)row.get("ARTIFACT_ID"));Map<String,Object> apk=artifact==null?Map.of():db.queryForMap("SELECT sha256,size_bytes FROM app_apks WHERE id=?",artifact.toString());return new Command(UUID.fromString((String)row.get("ID")),Action.valueOf((String)row.get("ACTION")),(String)row.get("PACKAGE_NAME"),(String)row.get("PERMISSION_NAME"),artifact,(String)apk.get("SHA256"),(Long)apk.get("SIZE_BYTES"),((Timestamp)row.get("EXPIRES_AT")).toInstant());}
    @Transactional public Map<String,Object> start(UUID device,UUID id){lock(device);expire(device);var rows=db.queryForList("SELECT * FROM app_commands WHERE id=? AND device_id=? FOR UPDATE",id.toString(),device.toString());if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);var row=rows.get(0);String state=(String)row.get("STATE");if(!Set.of("PENDING","RUNNING").contains(state))throw new ResponseStatusException(HttpStatus.CONFLICT);if(state.equals("PENDING")){if(Set.of("INSTALL","UNINSTALL").contains(row.get("ACTION"))&&db.queryForObject("SELECT COUNT(*) FROM commands WHERE device_id=? AND state='PENDING' AND enabled=TRUE",Integer.class,device.toString())>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Protection is queued; install cannot start");db.update("UPDATE app_commands SET state='RUNNING',started_at=?,detail='Executing on terminal' WHERE id=?",now(),id.toString());audit("device","APP_STARTED",device,id,(String)row.get("ACTION"));}return Map.of("command",command(row));}
    @Transactional public Map<String,Object> ack(UUID device,UUID id,Ack ack){lock(device);var rows=db.queryForList("SELECT * FROM app_commands WHERE id=? AND device_id=? FOR UPDATE",id.toString(),device.toString());if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);var row=rows.get(0);String state=(String)row.get("STATE");if(Set.of("SUCCEEDED","FAILED").contains(state))return view(id);if(!state.equals("RUNNING"))throw new ResponseStatusException(HttpStatus.CONFLICT);if(ack.observedApp()!=null&&row.get("PACKAGE_NAME")!=null&&!row.get("PACKAGE_NAME").equals(ack.observedApp().packageName()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);db.update("UPDATE app_commands SET state=?,detail=?,result_json=?,completed_at=? WHERE id=?",ack.success()?"SUCCEEDED":"FAILED",ack.detail(),encode(ack),now(),id.toString());audit("device",ack.success()?"APP_SUCCEEDED":"APP_FAILED",device,id,ack.detail());return view(id);}
    @Transactional public boolean installInProgress(UUID device){expire(device);return db.queryForObject("SELECT COUNT(*) FROM app_commands WHERE device_id=? AND state='RUNNING' AND action IN ('INSTALL','UNINSTALL')",Integer.class,device.toString())>0;}
    @Transactional public void revoke(UUID device){db.update("UPDATE app_commands SET state='CANCELLED',detail='Device access revoked' WHERE device_id=? AND state IN ('PENDING','RUNNING')",device.toString());}
    public Map<String,Object> upload(InputStream input,String filename)throws Exception{
        Files.createDirectories(directory);try{Files.setPosixFilePermissions(directory,PosixFilePermissions.fromString("rwx------"));}catch(UnsupportedOperationException ignored){}
        UUID id=UUID.randomUUID();Path temp=Files.createTempFile(directory,"upload-",".tmp"),destination=directory.resolve(id+".apk");boolean committed=false;
        try{try{Files.setPosixFilePermissions(temp,PosixFilePermissions.fromString("rw-------"));}catch(UnsupportedOperationException ignored){}MessageDigest hash=MessageDigest.getInstance("SHA-256");long size=0;try(OutputStream output=Files.newOutputStream(temp)){byte[] buffer=new byte[65536];int n;while((n=input.read(buffer))!=-1){size+=n;if(size>MAX_APK)throw new ResponseStatusException(HttpStatus.PAYLOAD_TOO_LARGE);hash.update(buffer,0,n);output.write(buffer,0,n);}}if(size==0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Empty APK");try(ZipFile zip=new ZipFile(temp.toFile())){if(zip.getEntry("AndroidManifest.xml")==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Not an APK");}catch(java.util.zip.ZipException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Not an APK");}String name=filename==null?"application.apk":filename.replaceAll("[^A-Za-z0-9._ -]","_");if(name.length()>150)name=name.substring(name.length()-150);String sha=HexFormat.of().formatHex(hash.digest());Files.move(temp,destination,StandardCopyOption.ATOMIC_MOVE);db.update("INSERT INTO app_apks(id,filename,size_bytes,sha256,uploaded_at) VALUES(?,?,?,?,?)",id.toString(),name,size,sha,now());committed=true;audit("administrator","APK_UPLOADED",null,null,name+"; SHA-256 "+sha);return db.queryForMap("SELECT * FROM app_apks WHERE id=?",id.toString());}finally{Files.deleteIfExists(temp);if(!committed)Files.deleteIfExists(destination);}
    }
    public Path download(UUID device,UUID artifact){device(device);if(db.queryForObject("SELECT COUNT(*) FROM app_commands WHERE device_id=? AND artifact_id=? AND state='RUNNING' AND started_at>?",Integer.class,device.toString(),artifact.toString(),Timestamp.from(clock.instant().minusSeconds(600)))==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND);Path file=directory.resolve(artifact+".apk");if(!Files.isRegularFile(file))throw new ResponseStatusException(HttpStatus.NOT_FOUND);return file;}
}
